  1	package shop;
  2	
  3	import com.zaxxer.hikari.HikariConfig;
  4	import com.zaxxer.hikari.HikariDataSource;
  5	
  6	import java.math.BigDecimal;
  7	import java.sql.Connection;
  8	import java.sql.PreparedStatement;
  9	import java.sql.ResultSet;
 10	import java.sql.SQLException;
 11	import java.sql.Statement;
 12	import java.time.Instant;
 13	import java.time.OffsetDateTime;
 14	import java.time.ZoneOffset;
 15	import java.util.ArrayList;
 16	import java.util.Collection;
 17	import java.util.List;
 18	import java.util.Optional;
 19	import java.util.TreeSet;
 20	import java.util.function.Function;
 21	
 22	/**
 23	 * Armazenamento em PostgreSQL. Duas instâncias podem usar o mesmo banco: a consistência vem de
 24	 * transações e travas de linha (SELECT ... FOR UPDATE), nunca de memória do processo.
 25	 */
 26	class JdbcStore implements Store, AutoCloseable {
 27	    private static final long SCHEMA_LOCK_ID = 7_351_001L;
 28	
 29	    private static final List<String> SCHEMA = List.of(
 30	            """
 31	            CREATE TABLE IF NOT EXISTS products (
 32	              sku text PRIMARY KEY,
 33	              name text NOT NULL,
 34	              price numeric(14,2) NOT NULL,
 35	              weight_kg numeric(10,3) NOT NULL,
 36	              stock integer NOT NULL CHECK (stock >= 0),
 37	              discontinued boolean NOT NULL
 38	            )""",
 39	            """
 40	            CREATE TABLE IF NOT EXISTS customers (
 41	              cpf text PRIMARY KEY,
 42	              email text NOT NULL,
 43	              credit_balance numeric(14,2) NOT NULL DEFAULT 0
 44	            )""",
 45	            """
 46	            CREATE TABLE IF NOT EXISTS orders (
 47	              id text PRIMARY KEY,
 48	              cpf text NOT NULL,
 49	              email text NOT NULL,
 50	              status text NOT NULL,
 51	              created_at timestamptz NOT NULL,
 52	              summary text NOT NULL,
 53	              tracking_code text,
 54	              paid_at timestamptz,
 55	              transaction_id text
 56	            )""",
 57	            "CREATE INDEX IF NOT EXISTS orders_cpf_status_idx ON orders (cpf, status)",
 58	            """
 59	            CREATE TABLE IF NOT EXISTS order_items (
 60	              order_id text NOT NULL REFERENCES orders (id),
 61	              position integer NOT NULL,
 62	              sku text NOT NULL,
 63	              quantity integer NOT NULL,
 64	              PRIMARY KEY (order_id, position)
 65	            )""",
 66	            """
 67	            CREATE TABLE IF NOT EXISTS payment_events (
 68	              order_id text NOT NULL,
 69	              transaction_id text NOT NULL,
 70	              error_code text,
 71	              http_status integer NOT NULL,
 72	              PRIMARY KEY (order_id, transaction_id)
 73	            )""",
 74	            """
 75	            CREATE TABLE IF NOT EXISTS notifications (
 76	              id bigserial PRIMARY KEY,
 77	              cpf text NOT NULL,
 78	              type text NOT NULL,
 79	              order_id text NOT NULL,
 80	              status text NOT NULL
 81	            )""",
 82	            "CREATE INDEX IF NOT EXISTS notifications_cpf_idx ON notifications (cpf, id)");
 83	
 84	    private final HikariDataSource dataSource;
 85	
 86	    JdbcStore(String url, String user, String password) {
 87	        HikariConfig config = new HikariConfig();
 88	        config.setJdbcUrl(url);
 89	        config.setUsername(user);
 90	        config.setPassword(password);
 91	        config.setMaximumPoolSize(10);
 92	        config.setInitializationFailTimeout(60_000);
 93	        this.dataSource = new HikariDataSource(config);
 94	        initSchema();
 95	    }
 96	
 97	    /** Cria tabelas e catálogo; seguro com duas instâncias subindo ao mesmo tempo. */
 98	    private void initSchema() {
 99	        try (Connection c = dataSource.getConnection()) {
100	            c.setAutoCommit(true);
101	            try (Statement st = c.createStatement()) {
102	                st.execute("SELECT pg_advisory_lock(" + SCHEMA_LOCK_ID + ")");
103	            }
104	            try {
105	                try (Statement st = c.createStatement()) {
106	                    for (String ddl : SCHEMA) st.execute(ddl);
107	                }
108	                try (PreparedStatement ps = c.prepareStatement(
109	                        "INSERT INTO products (sku, name, price, weight_kg, stock, discontinued) VALUES (?,?,?,?,?,?) "
110	                                + "ON CONFLICT (sku) DO NOTHING")) {
111	                    for (Product p : Catalog.initial()) {
112	                        ps.setString(1, p.sku());
113	                        ps.setString(2, p.name());
114	                        ps.setBigDecimal(3, p.price());
115	                        ps.setBigDecimal(4, p.weightKg());
116	                        ps.setInt(5, p.stock());
117	                        ps.setBoolean(6, p.discontinued());
118	                        ps.executeUpdate();
119	                    }
120	                }
121	            } finally {
122	                try (Statement st = c.createStatement()) {
123	                    st.execute("SELECT pg_advisory_unlock(" + SCHEMA_LOCK_ID + ")");
124	                }
125	            }
126	        } catch (SQLException e) {
127	            throw new IllegalStateException("Could not initialize database", e);
128	        }
129	    }
130	
131	    @Override
132	    public <T> T transaction(Function<Tx, T> work) {
133	        try (Connection c = dataSource.getConnection()) {
134	            c.setAutoCommit(false);
135	            try {
136	                T result = work.apply(new JdbcTx(c));
137	                c.commit();
138	                return result;
139	            } catch (Throwable t) {
140	                try {
141	                    c.rollback();
142	                } catch (SQLException ignored) {
143	                    // a falha original é a que importa
144	                }
145	                throw t;
146	            }
147	        } catch (SQLException e) {
148	            throw new IllegalStateException(e);
149	        }
150	    }
151	
152	    @Override
153	    public void close() {
154	        dataSource.close();
155	    }
156	
157	    private static OffsetDateTime ts(Instant i) {
158	        return i == null ? null : OffsetDateTime.ofInstant(i, ZoneOffset.UTC);
159	    }
160	
161	    private static final class JdbcTx implements Tx {
162	        private final Connection c;
163	
164	        JdbcTx(Connection c) {
165	            this.c = c;
166	        }
167	
168	        private <T> T sql(SqlWork<T> work) {
169	            try {
170	                return work.run();
171	            } catch (SQLException e) {
172	                throw new IllegalStateException(e);
173	            }
174	        }
175	
176	        private static Product product(ResultSet rs) throws SQLException {
177	            return new Product(rs.getString("sku"), rs.getString("name"), rs.getBigDecimal("price"),
178	                    rs.getBigDecimal("weight_kg"), rs.getInt("stock"), rs.getBoolean("discontinued"));
179	        }
180	
181	        public Optional<Product> findProduct(String sku) {
182	            return sql(() -> {
183	                try (PreparedStatement ps = c.prepareStatement("SELECT * FROM products WHERE sku = ?")) {
184	                    ps.setString(1, sku);
185	                    try (ResultSet rs = ps.executeQuery()) {
186	                        return rs.next() ? Optional.of(product(rs)) : Optional.empty();
187	                    }
188	                }
189	            });
190	        }
191	
192	        public List<Product> lockProducts(Collection<String> skus) {
193	            return sql(() -> {
194	                List<Product> result = new ArrayList<>();
195	                for (String sku : new TreeSet<>(skus)) {
196	                    try (PreparedStatement ps = c.prepareStatement("SELECT * FROM products WHERE sku = ? FOR UPDATE")) {
197	                        ps.setString(1, sku);
198	                        try (ResultSet rs = ps.executeQuery()) {
199	                            if (rs.next()) result.add(product(rs));
200	                        }
201	                    }
202	                }
203	                return result;
204	            });
205	        }
206	
